INSERT INTO `events` (`id`, `events_headlines`, `events_details`, `events_file`, `events_status`, `events_creation_time`, `sort_order`) VALUES
(1, 'ঈদে মিলাদুন্নবী উপলক্ষে ভবানীগঞ্জ বহুমুখী উচ্চ বিদ্যালয়ে জমকালো অনুষ্ঠান', 'প্রিয় নবী হজরত মুহাম্মদ (সঃ) এর জন্মদিন স্মরণ করে ঈদে মিলাদুন্নবী উপলক্ষে ভবানীগঞ্জ বহুমুখী উচ্চ বিদ্যালয়ে একটি বর্ণাঢ্য ও শিক্ষামূলক অনুষ্ঠানের আয়োজন করা হয়েছে। বিদ্যালয়ের শিক্ষক, শিক্ষার্থী এবং অভিভাবকদের বিশাল সমাবেশে এই পবিত্র দিনটি যথাযথ মর্যাদায় পালিত হয়।\r\n**অনুষ্ঠানের প্রধান আয়োজনা**\r\nসকাল ৯টায় শুরু হওয়া এই অনুষ্ঠানে প্রথমেই জাতীয় সংগীত পরিবেশন করা হয়। এরপর স্কুলের প্রধান শিক্ষক সিরাজাম মুনির অনুষ্ঠানটি উদ্বোধন করেন এবং রাসূল (সঃ) এর জীবন ও শিক্ষা সম্পর্কে একটি তথ্যবহুল বক্তৃতা প্রদান করেন। তিনি বলেন যে, \"প্রিয় নবী হজরত মুহাম্মদ (সঃ) আমাদের সকল কাজে অনুপ্রেরণা এবং আদর্শ। তাঁর জীবনাদর্শ অনুসরণ করে আমরা একটি উন্নত সমাজ গড়ে তুলতে পারি।\"\r\n\r\n**শিক্ষার্থীদের অংশগ্রহণ**\r\nঅনুষ্ঠানটিকে আরও আকর্ষণীয় করার জন্য স্কুলের বিভিন্ন শ্রেণীর ছাত্র-ছাত্রীরা নানা ধরনের সাংস্কৃতিক কর্মসূচি উপস্থাপন করে। এর মধ্যে ছিল:\r\n\r\n- রাসূল (সঃ) এর জীবনী নিয়ে আবেগপূর্ণ নাত পরিবেশন\r\n- নবীজির শিক্ষা ও আদর্শ সম্পর্কে শিক্ষণীয় গীতি\r\n- স্কুলের সঙ্গীত দল কর্তৃক ইসলামী সংগীত পরিবেশন\r\n- ষষ্ঠ ও সপ্তম শ্রেণীর শিক্ষার্থীদের দ্বারা আলোচনা সভা\r\n- বিভিন্ন ক্লাসের শিক্ষার্থীদের কবিতা আবৃত্তি\r\n\r\n**ধর্মীয় অনুষ্ঠান ও ওয়াজ**\r\n\r\nবিদ্যালয়ের ধর্মীয় শিক্ষক জনবা বোরহান উদ্দিন সাহেব রাসূল (সঃ) এর জীবন ও তাঁর সুন্নতের গুরুত্ব সম্পর্কে একটি দীর্ঘ ও তথ্যপূর্ণ ওয়াজ করেন। তিনি উপস্থিত সকলকে নবীজির আদর্শ অনুসরণে আহ্বান জানান।\r\n\r\nবিদ্যালয়ের সহকারী শিক্ষকরা অনুষ্ঠানটির সুন্দর আয়োজন ও সফল পরিচালনায় গুরুত্বপূর্ণ ভূমিকা পালন করেন। তারা নিশ্চিত করেন যে প্রতিটি শিক্ষার্থী অনুষ্ঠানে যথাযথ অংশগ্রহণ করতে পারে।\r\nছাত্র-ছাত্রীদের বক্তব্যে যা উঠে এসেছিল, \"আমরা এই অনুষ্ঠান থেকে অনুপ্রাণিত হয়ে আমাদের জীবনে নবীজির শিক্ষা প্রয়োগ করব এবং একজন সৎ ও দায়িত্বশীল নাগরিক হয়ে গড়ে উঠব।\"\r\n\r\nপ্রধান শিক্ষক ঘোষণা করেন যে বছরের প্রতিটি ইসলামী উৎসবে স্কুল এভাবেই সমন্বিত অনুষ্ঠানের আয়োজন করবে যা শিক্ষার্থীদের ধর্মীয় মূল্যবোধ ও সাংস্কৃতিক সচেতনতা বৃদ্ধি করে।\r\n[img:2]\r\nঅনুষ্ঠানটি দুপুর ১ টায় সফলভাবে সমাপ্ত হয়। উপস্থিত শিক্ষক ও শিক্ষার্থীরা এই অনুষ্ঠান থেকে ধর্মীয় ও নৈতিক শিক্ষা লাভ করে সন্তুষ্টি প্রকাশ করেন।', '20260912065855_5a37a794.jpg', '1', '2026-09-12 04:58:55.942948', 40),
(2, 'এসএসসি ২০২৬ পরীক্ষা মোকাবেলায় শিক্ষার্থী ও অভিভাবকদের জন্য দিক নির্দেশনা সমাবেশ', 'আগামী এসএসসি ২০২৬ পরীক্ষায় সর্বোচ্চ সাফল্য অর্জনের জন্য দশম শ্রেণির ছাত্র-ছাত্রী এবং তাদের অভিভাবকদের জন্য একটি বিস্তৃত দিক নির্দেশনামূলক সমাবেশের আয়োজন করা হয়েছে। এই অনুষ্ঠানে শিক্ষার্থীদের পড়াশোনার কৌশল, সময় ব্যবস্থাপনা, পরীক্ষায় সাফল্যের সূত্র এবং অভিভাবকদের ভূমিকা নিয়ে বিস্তারিত আলোচনা করা হয়।\r\n\r\n**অনুষ্ঠানের আয়োজন ও উদ্বোধন**\r\n\r\nবিদ্যালয়ের হলরুমে এই অনুষ্ঠানটি অনুষ্ঠিত হয়। প্রধান শিক্ষক সিরাজাম মুনির অনুষ্ঠানটি উদ্বোধন করে বলেন, \"এসএসসি পরীক্ষা একটি গুরুত্বপূর্ণ মাইলফলক যা আমাদের শিক্ষার্থীদের ভবিষ্যতের গতিপথ নির্ধারণ করে। সঠিক পরিকল্পনা, কঠোর পরিশ্রম এবং নিয়মানুবর্তিতার মাধ্যমে সকল শিক্ষার্থীই সফলতা অর্জন করতে পারে।\"\r\n\r\nবিদ্যালয় পরিচালনা কমিটির সদস্য সফিকুল ইসলাম সবুজ সাহেব জানান যে, পরীক্ষার আগে বিদ্যালয়ে সাপ্তাহিক ক্লাস টেস্ট এবং মাসিক মূল্যায়ন পরীক্ষার আয়োজন করা হবে। এই পরীক্ষাগুলিতে যারা দুর্বল পারফরম্যান্স দেখাবে তাদের জন্য অতিরিক্ত গাইডেন্স ক্লাস নির্ধারণ করা হবে। শীর্ষ পারফরমাররা পুরস্কৃত করা হবে যা তাদের আত্মবিশ্বাস বৃদ্ধি করবে।\r\n\r\nপ্রধান শিক্ষক (এসএসসি ২০২৫) খারাপ ফলাফলের কারণগুলি বিশ্লেষণ করে উপস্থাপন করেন:\r\n\r\n**সমস্যাগুলি ছিল:**\r\n -অপর্যাপ্ত নিয়মিত পড়াশোনা এবং অলসতা,\r\n- নোট তৈরিতে গুরুত্ব না দেওয়া,\r\n- পুরনো প্রশ্নপত্র সমাধানে অনীহা,\r\n- পরীক্ষা নিয়ে অপ্রয়োজনীয় দুশ্চিন্তা এবং পরীক্ষাভীতি,\r\n- অভিভাবকদের সাথে অপর্যাপ্ত যোগাযোগ,\r\n- স্বাস্থ্য ও পুষ্টি সংক্রান্ত সমস্যা\r\n\r\n**উত্তরণের উপায়:**\r\n- প্রতিদিন নির্দিষ্ট সময়ে পড়াশোনা শুরু ও শেষ করা,\r\n- শিক্ষকদের সাথে নিয়মিত সেশনে অংশগ্রহণ,\r\n- গ্রুপ স্টাডি এবং পিয়ার লার্নিং এ উৎসাহিত করা,\r\n- মানসিক চাপ কমাতে খেলাধুলা ও ব্যায়াম,\r\n- সঠিক ঘুম এবং স্বাস্থ্যকর খাবার খাওয়া,\r\n- দুর্বল শিক্ষার্থীদের টিউটরিয়াল এবং অতিরিক্ত ক্লাসের ব্যবস্থা\r\n\r\n**অভিভাবকদের করণীয়:**\r\n- সন্তানের পড়াশোনার অগ্রগতি নিয়মিত পর্যবেক্ষণ করা,\r\n- শিক্ষকদের সাথে মাসিক মিটিং করে অবস্থান জানা,\r\n- বাড়িতে অনুকূল পড়াশোনার পরিবেশ তৈরি করা,\r\n- সন্তানের পুষ্টি ও স্বাস্থ্যের প্রতি যত্ন নেওয়া,\r\n- মোবাইল ফোন ও অনলাইন গেমসের অপব্যবহার নিয়ন্ত্রণ করা,\r\n- সন্তানকে অতিরিক্ত চাপ না দিয়ে উৎসাহিত করা,\r\n- নিয়মিত ছোটখাটো পুরস্কার দিয়ে অনুপ্রাণিত করা।\r\n\r\n**প্রশ্নোত্তর ও মতবিনিময় সেশন**\r\n\r\nঅনুষ্ঠানের মধ্যবর্তী অংশে শিক্ষার্থী এবং অভিভাবক উভয়েই তাদের সমস্যা ও প্রশ্ন নিয়ে এসেছেন। বিভিন্ন প্রশ্নের উত্তর দেওয়া হয়েছে:\r\n\r\n- \"পড়াতে মনোযোগ দিতে পারি না, কী করব?\" \r\n- \"বিভিন্ন বিষয়ে দুর্বল, সব বিষয় একসাথে পড়তে পারি না?\" \r\n- \"পরীক্ষার হলে আতঙ্কিত হয়ে যাই\"\r\n- \"ছেলেকে নিয়ন্ত্রণ করতে পারছি না\"\r\n\r\nএই সকল প্রশ্নের উত্তরে শিক্ষা বিশেষজ্ঞরা বাস্তবসম্মত পরামর্শ প্রদান করেন।\r\n\r\n**বিশেষ পাঠ্যক্রম ও অতিরিক্ত ক্লাসের ঘোষণা**\r\n\r\nবিদ্যালয় পরিচালনা পক্ষ থেকে জানানো হয় যে:\r\n\r\n- দুর্বল শিক্ষার্থীদের জন্য সপ্তাহে তিনদিন বিশেষ ব্যাচে অতিরিক্ত ক্লাস হবে,\r\n- A+ প্রত্যাশীদের জন্য উন্নত স্তরের সমস্যা সমাধান সেশন থাকবে\r\n- প্রতি দিন স্কুল সময়ের আগে-পরে শিক্ষকদের অফিস আওয়ার থাকবে যখন শিক্ষার্থীরা তাদের সমস্যা নিয়ে আসতে পারবে\r\n- মাসিক মডেল টেস্ট পরীক্ষা এবং ফলাফল বিশ্লেষণ করা হবে\r\n\r\n**সফল শিক্ষার্থীদের অভিজ্ঞতা শেয়ার করা**\r\n\r\n**অনুষ্ঠানের সমাপনী মন্তব্য**\r\n\r\nপ্রধান শিক্ষক সমাপনীতে বলেন, \"আগামী এসএসসি পরীক্ষায় ভবানীগঞ্জ বহুমুখী উচ্চ বিদ্যালয়ের সকল শিক্ষার্থী সফল হবে - এটাই আমাদের লক্ষ্য। শিক্ষক, শিক্ষার্থী এবং অভিভাবকদের সমন্বিত প্রচেষ্টায় এই লক্ষ্য অর্জনযোগ্য। আমরা সকলে একসাথে কাজ করব এবং সফলতা আমাদের হাতের মুঠোয়।\"\r\n\r\nউপস্থিত সকল শিক্ষার্থী ও অভিভাবক অনুষ্ঠান থেকে অনুপ্রাণিত হয়ে ফিরে যান এবং এসএসসি ২০২৬ পরীক্ষায় সাফল্যের জন্য দৃঢ় সংকল্পবদ্ধ হন।', '20260912072302_54a6b821.jpg', '1', '2026-09-12 05:23:02.938960', 50),
(3, 'নতুন কুড়ি রেজিস্ট্রেশনে উদ্বুদ্ধকরণে জেলা ক্রীড়া সংস্থার সদস্য সচিব জনাব মহসিন কবির স্বপনের বিদ্যালয় পরিদর্শন', 'নতুন কুড়ির রেজিস্ট্রেশনে উদ্বুদ্ধ করার জন্য জেলা ক্রীড়া সংস্থার সম্মানিত সদস্য সচিব জনাব মহসিন কবির স্বপন আজ ভবানীগঞ্জ বহুমুখী উচ্চ বিদ্যালয়ে আসেন। এই অনুষ্ঠানে তিনি শিক্ষার্থীদের সাথে নতুন কুড়ির গুরুত্ব, সুস্বাস্থ্য ও শারীরিক বিকাশ এবং নতুন কুড়ি রেজিস্ট্রেশনের সুদূরপ্রসারী ফলাফল নিয়ে বিস্তারিত মতবিনিময় করেন।\r\n\r\nসকাল ১০টায় বিদ্যালয়ের খেলার মাঠে জনাব মহসিন কবির স্বপনকে উষ্ণ সংবর্ধনা জানানো হয়। বিদ্যালয়ের প্রধান শিক্ষক সিরাজাম মুনির তাকে বিশেষ সম্মান জানিয়ে স্বাগত জানান। এই অনুষ্ঠানে বিদ্যালয়ের সকল শিক্ষার্থী, শারীরিক শিক্ষক এবং খেলাধুলায় আগ্রহী শিক্ষকরা উপস্থিত ছিলেন।\r\n\r\nস্বপন ভাই প্রথমে শিক্ষার্থীদের সাথে পরিচয় হয়ে একটি অত্যন্ত প্রাণবন্ত এবং অনুপ্রেরণামূলক বক্তৃতা প্রদান করেন।\r\n\r\n\r\nজনাব মহসিন কবির স্বপন বিস্তারিতভাবে বুঝিয়ে দেন যে, নতুন কুড়ির বিভিন্ন ইভেন্ট  কীভাবে শিক্ষার্থীদের শারীরিক ও মানসিক বিকাশে অবদান রাখে:\r\n\r\nতিনি বলেন, \"আজকাল ছেলেমেয়েরা মোবাইল ফোন এবং কম্পিউটারের পর্দার সামনে বসে থাকে। এর ফলে তাদের শারীরিক স্বাস্থ্য হ্রাস পাচ্ছে। কুড়ি খেলার মতো একটি ঐতিহ্যবাহী প্লাটফর্মের খেলায় অংশগ্রহণ করলে তারা সুস্থ, সবল এবং সক্রিয় থাকবে।\"\r\n\r\n**নতুন কুড়ি রেজিস্ট্রেশনের উদ্দেশ্য**\r\n১. **তরুণ প্রতিভা আবিষ্কার:** দেশের বিভিন্ন বিদ্যালয় থেকে প্রতিভাবান খেলোয়াড় খুঁজে বের করা\r\n\r\n২. **জাতীয় স্তরের প্রতিযোগিতা:** নতুন খেলোয়াড়দের জাতীয় ও আন্তর্জাতিক প্রতিযোগিতায় অংশগ্রহণের সুযোগ দেওয়া\r\n\r\n৩. **শারীরিক শিক্ষা প্রচার:** শিক্ষা প্রতিষ্ঠানে শারীরিক শিক্ষার গুরুত্ব বৃদ্ধি করা\r\n\r\n৪. **সামাজিক উন্নয়ন:** খেলার মাধ্যমে সামাজিক দক্ষতা এবং নেতৃত্ব গুণাবলী বিকাশ\r\n\r\n**নতুন কুড়ি রেজিস্ট্রেশনের সুদূরপ্রসারী ফলাফল**\r\n\r\nজনাব মহসিন কবির স্বপন বলেন যে এই নতুন রেজিস্ট্রেশন প্রোগ্রাম দীর্ঘমেয়াদী এবং গভীর প্রভাব ফেলবে:\r\n\r\n**ব্যক্তিগত স্তরে:**\r\n- খেলোয়াড়দের শারীরিক ও মানসিক দক্ষতা বৃদ্ধি\r\n- ক্যারিয়ারের নতুন সম্ভাবনা সৃষ্টি\r\n- আত্মসম্মান ও আত্মবিশ্বাস বৃদ্ধি\r\n- অসুস্থতা ও রোগ-ব্যাধি থেকে সুরক্ষা\r\n\r\n**পারিবারিক স্তরে:**\r\n- পরিবারের গর্ব এবং খ্যাতি বৃদ্ধি\r\n- পরিবারের সদস্যদের মধ্যে সুস্বাস্থ্যের সংস্কৃতি\r\n\r\n**সামাজিক স্তরে:**\r\n- সমাজে দক্ষ ও স্বাস্থ্যবান মানুষের সংখ্যা বৃদ্ধি\r\n- খেলাধুলার প্রতি মানুষের আগ্রহ বৃদ্ধি\r\n- সামাজিক সম্পর্ক ও বন্ধুত্ব গভীর করা\r\n\r\n**জাতীয় স্তরে:**\r\n- আন্তর্জাতিক পর্যায়ে বাংলাদেশের প্রতিনিধিত্ব\r\n- আমাদের সাংস্কৃতিক ঐতিহ্যের প্রচার ও সংরক্ষণ\r\n- দেশের ক্রীড়া জগতে নতুন মাত্রা যোগ করা\r\n- ক্রীড়া উন্নয়নে বিনিয়োগের সুযোগ\r\n\r\n** নতুন কুঁড়ি রেজিস্ট্রেশনের সুবিধা:**\r\n- জেলা পর্যায়ের প্রশিক্ষণ সুবিধা\r\n- জাতীয় প্রতিযোগিতায় অংশগ্রহণের সুযোগ\r\n- স্পন্সরশিপ এবং বৃত্তির সম্ভাবনা\r\n- ক্রীড়া পেশায় ক্যারিয়ারের সুযোগ\r\n- বিশেষ স্বীকৃতি এবং পুরস্কার\r\n\r\n\r\n\r\n\r\n**প্রধান শিক্ষকের আশ্বাস**\r\n\r\nপ্রধান শিক্ষক সিরাজাম মুনির বলেন, \"আমরা এই উদ্যোগকে সর্বোচ্চ গুরুত্ব দেব এবং প্রয়োজনীয় সহায়তা প্রদান করব। আমাদের বিদ্যালয় শুধুমাত্র একাডেমিক শিক্ষা নয়, সর্বাঙ্গীণ উন্নয়নে বিশ্বাস করে। নতুন কুঁড়ির  মত ইবেন্ট আমাদের শিক্ষার্থীদের মানবিক এবং সাংস্কৃতিক মূল্যবোধ বিকাশে অবদান রাখে।\"\r\nজনাব মহসিন কবির স্বপন স্কুল ছেড়ে যাওয়ার আগে শিক্ষকদের লক্ষ্য করে বলেন, \"আপনারা আমাদের শিক্ষার্থীদের ভবিষ্যত গঠনের দায়িত্বশীল। তাদের শুধু বই পড়ানোর পাশাপাশি শারীরিকভাবে সক্রিয় এবং আমাদের সাংস্কৃতিক ঐতিহ্যের প্রতি সচেতন করে তুলুন।\"\r\n\r\n**সমাপনী মন্তব্য**\r\n\r\nবিদ্যালয়ের দিকে তাকিয়ে জনাব মহসিন কবির স্বপন বলেন, \"আমি নিশ্চিত যে ভবানীগঞ্জ বহুমুখী উচ্চ বিদ্যালয় থেকে আগামী দিনে অনেক প্রতিভাবান খেলোয়াড় আসবে যারা আমাদের দেশের প্রতিনিধিত্ব করবে আন্তর্জাতিক পর্যায়ে। এই স্বপ্ন বাস্তবায়নে আপনাদের সহযোগিতা প্রয়োজন।\"\r\n\r\nঅনুষ্ঠানটি শেষ হয় জনাব মহসিন কবির স্বপনের  সাথে শিক্ষার্থী এবং শিক্ষকদের একটি স্মৃতি ছবি তোলার মাধ্যমে। উপস্থিত সকল শিক্ষার্থী এই অনুষ্ঠান থেকে অনুপ্রাণিত হয়ে কুড়ি খেলায় নিয়মিত অংশগ্রহণ করার জন্য উৎসাহিত হয়। জাতীয় পর্যায়ে এই উদ্যোগ আমাদের তরুণদের শারীরিক ও মানসিক বিকাশে এবং আমাদের সাংস্কৃতিক ঐতিহ্য সংরক্ষণে একটি গুরুত্বপূর্ণ ভূমিকা রাখবে বলে আশা করা হচ্ছে।', '20260912074737_ce0d99a2.jpg', '1', '2026-09-12 05:47:37.656611', 30),
(5, 'ভবানীগঞ্জ বহুমুখী উচ্চ বিদ্যালয়ের ম্যানেজিং কমিটি নির্বাচন- ২০২৬ এর চূড়ান্ত ভোটার তালিকা প্রকাশ', '.', '20260912075202_df7e2915.jpg', '1', '2026-09-12 05:52:02.849707', 20),
(6, 'শিক্ষার মান উন্নয়নে ম্যানেজিং কমিটি এবং শিক্ষকদের গুরুত্বপূর্ণ মতবিনিময় সভা', 'বিদ্যালয়ের শিক্ষার মান উন্নয়ন, পরবর্তী এসএসসি পরীক্ষায় সাফল্য এবং বর্তমান সমস্যা সমাধান নিয়ে একটি গুরুত্বপূর্ণ মতবিনিময় সভা অনুষ্ঠিত হয়েছে। এই সভায় এড হক কমিটির সম্মানিত সভাপতি জনাব মাইনুদ্দিন চৌধুরী রিয়াজ সভাপতিত্ব করেন এবং বিদ্যালয়ের সকল শিক্ষক ও ম্যানেজিং কমিটির সদস্য উপস্থিত থেকে গঠনমূলক আলোচনা করেন।\r\n[img:2]\r\n**সভার আয়োজন ও উদ্বোধন**\r\n\r\nবিদ্যালয়ের অফিস কক্ষে বিকাল ৪টায় এই সভা শুরু হয়। এড হক কমিটির সভাপতি জনাব মাইনুদ্দিন চৌধুরী রিয়াজ সভা উদ্বোধন করে বলেন, \"আমাদের বিদ্যালয়ের শিক্ষার মান উন্নয়ন এবং শিক্ষার্থীদের সাফল্য নিশ্চিত করা আমাদের প্রধান লক্ষ্য। এই লক্ষ্য অর্জনের জন্য আমাদের সবাইকে একসাথে কাজ করতে হবে এবং কঠোর পরিশ্রম করতে হবে।\"\r\n\r\nতিনি আরও বলেন, \"গত কয়েক বছরের পরীক্ষার ফলাফল বিশ্লেষণ করলে দেখা যায় যে আমরা আমাদের লক্ষ্য অর্জনে সফল হতে পারিনি। এই ব্যর্থতার কারণগুলি চিহ্নিত করে সেগুলি দূর করার জন্য এই সভা আয়োজন করা হয়েছে।\"\r\n[img:1]\r\n**বিগত এসএসসি পরীক্ষার ফলাফল বিশ্লেষণ**\r\n\r\nবিদ্যালয়ের প্রধান শিক্ষক জনাব সিরাজাম মুনির সাহেব গত বছর (এসএসসি ২০২৫) এর খারাপ ফলাফলের বিস্তারিত বিশ্লেষণ উপস্থাপন করেন। তিনি বলেন:\r\n\r\n**খারাপ ফলাফলের কারণ:**\r\n\r\n১. **নিয়মিত পড়াশোনার অভাব:**\r\n   - শিক্ষার্থীরা নিয়মিত পাঠ্যক্রম অনুসরণ করেনি\r\n   - শ্রেণিকক্ষে মনোযোগ দিয়ে পড়াশোনা করেনি\r\n   - গৃহ-অধ্যয়ন এ সময় বরাদ্দ অপ্রতুল ছিল\r\n\r\n২. **পুরনো প্রশ্নপত্র সমাধানে অনীহা:**\r\n   - শিক্ষার্থীরা গত পাঁচ বছরের এসএসসি প্রশ্নপত্র সমাধান করেনি\r\n   - পরীক্ষার ধরন সম্পর্কে সচেতনতা ছিল না\r\n\r\n৩. **ক্লাস টেস্টের অনুপস্থিতি:**\r\n   - নিয়মিত ক্লাস টেস্ট শিক্ষার্থীদের অনুপস্থিতি\r\n   - শিক্ষার্থীদের অগ্রগতি মূল্যায়নের যথাযথ ব্যবস্থা ছিল না\r\n\r\n৪. **শিক্ষক-অভিভাবক যোগাযোগের ঘাটতি:**\r\n   - অভিভাবকরা তাদের সন্তানদের পড়াশোনা সম্পর্কে অবগত ছিলেন না\r\n   - শিক্ষক ও অভিভাবকদের মধ্যে কোনো নিয়মিত যোগাযোগ ছিল না\r\n\r\n৫. **মানসিক চাপ ও পরীক্ষাভীতি:**\r\n   - শিক্ষার্থীরা পরীক্ষা নিয়ে অপ্রয়োজনীয় দুশ্চিন্তা করেছে\r\n   - আত্মবিশ্বাসের অভাব ছিল\r\n\r\n**উন্নতির জন্য গৃহীতব্য পদক্ষেপ**\r\n\r\nসভায় আলোচনা করে পরবর্তী এসএসসি পরীক্ষায় ভালো ফলাফল নিশ্চিত করতে নিম্নোক্ত পদক্ষেপগুলি গ্রহণ করার সিদ্ধান্ত নেওয়া হয়:\r\n\r\n**১. নিয়মিত ক্লাস টেস্ট আয়োজন:**\r\n\r\n- প্রতিটি বিষয়ে সপ্তাহে একটি ক্লাস টেস্ট নিতে হবে\r\n- মাসিক মূল্যায়ন পরীক্ষা নেওয়া হবে\r\n- শিক্ষার্থীর অগ্রগতি ট্র্যাক করার জন্য একটি স্কোর শীট রক্ষা করতে হবে\r\n- দুর্বল পারফরমাররা অতিরিক্ত গাইডেন্স পাবে\r\n\r\n**২. পুরনো প্রশ্নপত্র সমাধান কর্মসূচি:**\r\n\r\n- গত পাঁচ বছরের এসএসসি প্রশ্নপত্র ক্লাসে সমাধান করা হবে\r\n- শিক্ষার্থীরা নিয়মিত অনুশীলনীতে প্রশ্নপত্র সমাধান করবে\r\n- পরীক্ষার ধরন ও প্যাটার্ন সম্পর্কে বিশেষ ক্লাস দেওয়া হবে\r\n\r\n**৩. শিক্ষক ও অভিভাবক সভা আয়োজন:**\r\n\r\n- প্রতি মাসে একবার শিক্ষক ও অভিভাবকদের যৌথ সভা অনুষ্ঠিত হবে\r\n- শিক্ষার্থীর অগ্রগতি সম্পর্কে অভিভাবকদের নিয়মিত অবহিত করা হবে\r\n- দুর্বল শিক্ষার্থীর অভিভাবকদের সাথে বিশেষ পরামর্শ সভা করা হবে\r\n- গৃহ-অধ্যয়ন সম্পর্কে অভিভাবকদের পরামর্শ দেওয়া হবে\r\n- আত্মবিশ্বাস বৃদ্ধির জন্য প্রেরণামূলক কার্যক্রম আয়োজন করা হবে\r\n- নিয়মিত ব্যায়াম ও খেলাধুলার ব্যবস্থা নিশ্চিত করা হবে\r\n\r\n**এসএসসি ফরম পূরণ বিষয়ে সিদ্ধান্ত**\r\n\r\nসভায় একটি গুরুত্বপূর্ণ বিষয় উঠে আসে - গত বছর এসএসসি ফরম পূরণের সময় অনেক অকৃতকার্য শিক্ষার্থী তাদের ফরম পূরণ করে। এসএসসি পরীক্ষার খারাফ ফলাফলের জন্য এটিও অন্যতম বড় একটি কারণ। এ বিষয়ে সভায় কঠোর নির্দেশ দেওয়া হয় যে:\r\nক্লাস টেস্ট ও নির্বাচনী পরীক্ষার ফলাফল যেসকল শিক্ষার্থীর সন্তোষজনক হবে না তাদের কোন অবস্থাতেই ফরম পূরণ করা হবে না।\r\n- কোন শিক্ষার্থী যেন পিছিয়ে না থাকে তার জন্য বিশেষ তদারকি করতে হবে\r\n- অভিভাবক ও শিক্ষকদের যৌথ উদ্যোগে এ সমস্যা সমাধান করতে হবে\r\n\r\n**অভিভাবক সদস্যের মন্তব্য**\r\n\r\nঅভিভাবক সদস্য জনাব সফিকুল ইসলাম সবুজ সভায় একটি গুরুত্বপূর্ণ মন্তব্য করেন। তিনি বলেন, \"অভিভাবক হিসেবে আমাদের দায়িত্ব অত্যন্ত গুরুত্বপূর্ণ। আমরা যদি আমাদের সন্তানদের পড়াশোনায় গুরুত্ব না দেই এবং শিক্ষকদের সাথে সহযোগিতা না করি তাহলে কোনো সাফল্য সম্ভব নয়। আমি সকল অভিভাবককে আহ্বান জানাচ্ছি যে তারা নিয়মিত স্কুলে যোগাযোগ করুক এবং তাদের সন্তানদের পড়াশোনায় সক্রিয়ভাবে অংশগ্রহণ করুক।\"\r\n\r\nতিনি আরও বলেন, \"বিদ্যালয় ও পরিবারের সমন্বিত প্রচেষ্টার মাধ্যমেই আমরা শিক্ষার্থীদের সফল করতে পারি। প্রতিটি শিক্ষার্থী আমাদের সম্ভাবনাময় ভবিষ্যত।\"\r\n\r\n**বিভিন্ন বিষয়ে গৃহীতব্য ব্যবস্থা**\r\n\r\n**শিক্ষার্থী শৃঙ্খলা:**\r\n- ক্লাসে উপস্থিতি কঠোরভাবে নিয়ন্ত্রণ করা হবে\r\n- অনিয়ন্ত্রিত আচরণের বিরুদ্ধে ব্যবস্থা নেওয়া হবে\r\n- শিক্ষার্থীদের শৃঙ্খলা এবং আচরণ সম্পর্কে অভিভাবকদের অবহিত করা হবে\r\n\r\n**বিশেষ ব্যবস্থা**\r\n\r\nসভায় আরও কয়েকটি বিশেষ ব্যবস্থা গ্রহণ করা হয়:\r\n\r\n১. প্রধান শিক্ষক কর্তৃক নিয়মিত অগ্রগতি রিপোর্ট ম্যানেজিং কমিটির সভাপতি মহোদয়কে প্রদান করবেন\r\n\r\n২. শিক্ষার্থী যারা বিশেষভাবে দুর্বল তাদের জন্য বিশেষ ক্লাস চালু করা হবে\r\n\r\n৩. উচ্চ পারফরমাররা পুরস্কৃত করা হবে যা অন্যদের অনুপ্রাণিত করবে\r\n\r\n৪. শিক্ষার্থীদের অংশগ্রহণ ও অবদান স্বীকৃতি দেওয়া হবে\r\n\r\n**প্রধান শিক্ষকের প্রতিশ্রুতি**\r\n\r\nপ্রধান শিক্ষক জনাব সিরাজাম মুনির  প্রতিশ্রুতি দেন যে, \"আমরা এই সকল পদক্ষেপ সম্পূর্ণ নিষ্ঠার সাথে বাস্তবায়ন করব। আমাদের লক্ষ্য পরবর্তী এসএসসি পরীক্ষায় ১০০% শিক্ষার্থীকে পাশ করানো এবং সর্বোচ্চ সংখ্যক শিক্ষার্থীকে ভালো ফলাফল প্রদান করা।\"\r\n\r\nতিনি বলেন, \"প্রতিটি শিক্ষক, কর্মচারী এবং ম্যানেজিং কমিটির সদস্যকে এই মিশনে অংশীদার হতে হবে। একসাথে কাজ করলে আমরা অবশ্যই সফল হব।\"\r\n\r\n**সভাপতির সমাপনী মন্তব্য**\r\n\r\nএড হক কমিটির সভাপতি জনাব মাইনুদ্দিন চৌধুরী রিয়াজ সভা সমাপ্ত করে বলেন, \"আজকের সভায় যে সিদ্ধান্তগুলি নেওয়া হয়েছে সেগুলি শিক্ষার্থীদের ভবিষ্যত গড়তে গুরুত্বপূর্ণ ভূমিকা পালন করবে। আমরা সবাই মিলে এই মিশনে প্রতিশ্রুতিবদ্ধ।\"\r\n\r\nতিনি সকল শিক্ষকগণের প্রতি কৃতজ্ঞতা প্রকাশ করে বলেন, \"এই সভায় যে সামগ্রিক সিদ্ধান্ত নেওয়া হয়েছে তা বাস্তবায়নের জন্য আমাদের সকলকে একসাথে কাজ করতে হবে। এভাবেই আমরা আমাদের বিদ্যালয়কে আরও উন্নত করতে পারব এবং শিক্ষার্থীদের সফল করতে পারব।\"\r\n\r\nঅনুষ্ঠানটি শেষ হয় প্রতিটি শিক্ষক ও ম্যানেজিং কমিটি সদস্যের প্রতি সভাপতির ধন্যবাদ জানানোর মাধ্যমে।', '20260912093104_fc09ee2e.jpg', '1', '2026-09-12 07:31:04.137049', 10);
