INSERT INTO `gallery_albums` (`id`, `title`, `event_name`, `album_year`, `cover_file`, `album_status`, `created_at`) VALUES
(1, 'সাধারণ অ্যালবাম', 'বিদ্যালয়ের ছবি', 2026, NULL, 1, '2026-09-13 01:27:56'),
(2, 'অবিভাবক সমাবেশ- মানবিক বিভাগ (এসএসসি-২০২৬ পরীক্ষার্থী ব্যাচ)', 'দশম শ্রেণির মানবিক বিভাগের অবিভাবক সমাবেশের খন্ড চিত্র।', 2026, NULL, 1, '2026-09-13 17:14:29'),
(3, 'অবিভাবক সমাবেশ- ব্যবসায় শিক্ষা বিভাগ (এসএসসি-২০২৬ পরীক্ষার্থী ব্যাচ)', 'দশম শ্রেণির ব্যবসায় শিক্ষা বিভাগের অবিভাবক সমাবেশের খন্ড চিত্র।', 2026, NULL, 1, '2026-09-13 17:22:57'),
(4, 'অবিভাবক সমাবেশ- বিজ্ঞান বিভাগ (এসএসসি-২০২৬ পরীক্ষার্থী ব্যাচ)', 'দশম শ্রেণির বিজ্ঞান বিভাগের অবিভাবক সমাবেশের খন্ড চিত্র।', 2026, NULL, 1, '2026-09-13 17:35:05'),
(5, 'ম্যানেজিং কমিটি নির্বাচন ২০২৬ এর  চূড়ান্ত ভোটার তালিকা প্রদর্শন', 'ভবানীগঞ্জ বহুমুখী উচ্চ বিদ্যালয়ের ম্যানেজিং কমিটি নির্বাচন ২০২৬ এর  চূড়ান্ত ভোটার তালিকা', 2026, '20260913195854_58e59e91.jpg', 1, '2026-09-13 17:58:55'),
(6, 'ম্যানেজিং কমিটি এবং শিক্ষকদের সাথে মতবিনিময় সভা।', 'শিক্ষার মান উন্নয়ন নিয়ে ম্যানেজিং কমিটি এবং শিক্ষকদের সাথে মতবিনিময় সভা। সভাপতিত্ব করেন এড হক কমিটির সম্মানিত সভাপতি জনাব মাইনুদ্দিন চৌধুরী রিয়াজ।', 2026, '20260913200403_4d8483fb.jpg', 1, '2026-09-13 18:04:04'),
(7, 'ঈদে মিলাদুন্নবী সঃ উপলক্ষে আয়োজিত  অনুষ্ঠান', 'ঈদে মিলাদুন্নবী সঃ উপলক্ষে আয়োজিত ভবানীগঞ্জ বহুমুখী উচ্চ বিদ্যালয় এর অনুষ্ঠান', 2026, '20260913200839_bc96af80.jpg', 1, '2026-09-13 18:08:39'),
(8, 'জুলাই গণঅভ্যুত্থান উপলক্ষে আয়োজিত অনুষ্ঠান', 'জুলাই গণঅভ্যুত্থান উপলক্ষে আয়োজিত অনুষ্ঠানের খন্ড চিত্র।', 2026, '20260913201726_0fbc292a.jpg', 1, '2026-09-13 18:17:27'),
(9, 'ক্রীড়া সামগ্রী গ্রহণ', 'লক্ষ্মীপুর সদর উপজেলানির্বাহী কর্মকর্তার সভাকক্ষে মাননীয় পানি সম্পদ মন্ত্রী জনাব শহীদ উদ্দিন চৌধুরী এ্যানী এমপি মহোদয় বিভিন্ন শিক্ষা প্রতিষ্ঠান প্রধানদের হাতে ক্রিড়া  সামগ্রী তুলে দেন।', 2026, NULL, 1, '2026-09-13 18:23:59'),
(10, 'বৃক্ষরোপণ কর্মসূচি', 'ভবানীগঞ্জ বহুমুখী উচ্চ বিদ্যালয় বৃক্ষরোপণ উপলক্ষে আয়োজিত কর্মযজ্ঞ', 2026, NULL, 1, '2026-09-13 18:29:52'),
(11, 'অভিভাবক সমাবেশ-02/05/2026', 'অভিভাবক সমাবেশ: দশম শ্রেণির বিজ্ঞান বিভাগ এবং ব্যবসা শিক্ষা। আয়োজনে ভবানীগঞ্জ বহুমুখী উচ্চ বিদ্যালয়।', 2026, NULL, 1, '2026-09-13 18:44:17'),
(12, 'এসএসসি-2026 পরীক্ষার্থী দের জন্য দোয়া, প্রবেশপত্র বিতরণ ও অষ্টম শ্রেণীর বৃত্তিপ্রাপ্তদের সংবর্ধনা', 'ভবানীগঞ্জ বহুমুখী উচ্চ বিদ্যালয়ের ২০২৬ খ্রিষ্টাব্দেরএসএসসি পরীক্ষার্থী দের জন্য দোয়া প্রবেশপত্র বিতরণ ও অষ্টম শ্রেণীর বৃত্তিপ্রাপ্তদের সংবর্ধনা', 2026, NULL, 1, '2026-09-13 18:53:28'),
(13, 'বার্ষিক ক্রীড়া-2026', 'বার্ষিক ক্রীড়া-2026', 2026, NULL, 1, '2026-09-13 19:10:54'),
(14, 'ক্রীড়া', 'ক্রীড়া', 2026, NULL, 1, '2026-09-13 19:15:21'),
(15, '৫৪ তম জাতীয় স্কুল মাদ্রাসা ও কারিগরি শিক্ষা ক্রীড়া প্রতিযোগিতা- ২০২৬', '৫৪ তম জাতীয় স্কুল মাদ্রাসা ও কারিগরি শিক্ষা ক্রীড়া প্রতিযোগিতা ২০২৬ এর ক্রিকেট চ্যাম্পিয়ন ভবানী গঞ্জ বহুমুখী উচ্চ বিদ্যালয়, সদর, লক্ষ্মীপুর।', 2026, NULL, 1, '2026-09-13 19:23:21'),
