INSERT INTO `main_notice` (`id`, `main_notice_text`, `main_notice_file`, `main_notice_status`, `main_notice_creation_time`) VALUES
(1, 'পবিত্র ঈদে মিলাদুন্নবী (সা:) উদযাপন উপলক্ষে ইসলামি সাংস্কৃতিক প্রতিযোগিতা - ২০২৬', '20260911154707_17aeacfa.jpg', 1, '2026-09-11 13:47:07.356406'),
(2, '৯ ডিসেম্বর আন্তর্জাতিক দুর্নীতিবিরোধী দিবস উদযাপন উপলক্ষে টিআইবির নিয়মিত আয়োজন ‘‘দুর্নীতিবিরোধী কার্টুন প্রতিযোগিতার’’ আয়োজন করা হয়েছে।', '20260911155546_ed5f7da7.jpg', 1, '2026-09-11 13:55:46.439979'),
(3, 'নতুন কুঁড়ি স্পোর্টস নির্দেশিকা-২০২৬', '20260911174724_fa04b7ee.pdf', 1, '2026-09-11 15:47:24.217998'),
(6, 'পবিত্র আখেরি চাহার সোম্বা  বুধবার (২০ আগস্ট) দিনটি বাংলাদেশসহ মুসলিম বিশ্বের দেশগুলোতে অত্যন্ত মর্যাদা ও গুরুত্বের সঙ্গে পালন করা হয়ে থাকে।  দেশের সব শিক্ষাপ্রতিষ্ঠান এ উপলক্ষে আজ বন্ধ থাকবে।\r\n\r\nপ্রাথমিক ও গণশিক্ষা মন্ত্রণালয় এবং শিক্ষা মন্ত্রণালয়ের বাৎসরিক ছুটির তালিকায় আখেরি চাহার সোম্বা উপলক্ষে এক দিন ছুটি রাখা হয়েছে। সে অনুযায়ী দেশের সব স্কুল, কলেজ, মাদ্রাসা, কারিগরি শিক্ষাপ্রতিষ্ঠান এবং সরকারি-বেসরকারি বিশ্ববিদ্যালয় বন্ধ থাকবে।', NULL, 1, '2026-09-11 17:04:20.051608'),
(8, 'শিক্ষকে তথ্য সম্বলিত এক্সেল ফাইল', '20260911201612_d6264249.xlsx', 1, '2026-09-11 18:16:12.311152');
