INSERT INTO `school_history` (`id`, `school_history`, `school_history_status`, `school_history_creation_time`) VALUES
(7, 'শিক্ষা মানুষের জীবনের শ্রেষ্ঠ অর্জন, আর আনুষ্ঠানিক শিক্ষার প্রসারে শিক্ষা প্রতিষ্ঠানের ভূমিকা অপরিসীম। পরিবেশের সাথে শিক্ষার্থীর সঠিক সংগতি বিধান এবং দেশপ্রেমিক, সৎ, আদর্শ ও নিষ্ঠাবান আলোকিত মানুষ গড়ার ব্রত নিয়ে ১৯৪৭ সালে প্রতিষ্ঠিত হয় **ভবানীগঞ্জ বহুমুখী উচ্চ বিদ্যালয়**। লক্ষ্মীপুর জেলার উপকূলীয় অঞ্চলের আদর্শ শিক্ষা প্রতিষ্ঠানগুলোর মধ্যে এটি নিঃসন্দেহে অন্যতম। লক্ষ্মীপুর সদর উপজেলার ভবানীগঞ্জ চৌরাস্তায়, লক্ষ্মীপুর-রামগতি মহাসড়কের পশ্চিম পার্শ্বে এক মনোরম ও শান্ত পরিবেশে প্রাচীন এই বিদ্যাপীঠটি অবস্থিত।\n\n**অবকাঠামো ও সুযোগ-সুবিধা**\nঅভিজ্ঞ ও দক্ষ শিক্ষকমণ্ডলীর তত্ত্বাবধানে পরিচালিত এই বিদ্যালয়ে রয়েছে সমৃদ্ধ অবকাঠামোগত সুযোগ-সুবিধা। সুবিশাল ক্যাম্পাসে একটি তিনতলা, একটি দোতলা ও একটি একতলা একাডেমিক ভবন, একটি সুপরিসর লাইব্রেরী, একটি উচ্চমানের বিজ্ঞানাগার এবং আধুনিক প্রযুক্তি শিক্ষার জন্য দুইটি কম্পিউটার ল্যাব রয়েছে। পদার্থবিদ্যা, রসায়ন ও জীববিদ্যার প্রায়োগিক পাঠগুলো বিজ্ঞানাগারে অত্যন্ত দক্ষতার সাথে সম্পন্ন করা হয়। এছাড়া বার্ষিক সভা-সমিতি ও ইনডোর গেমসের জন্য মূল ভবনে রয়েছে একটি বড় হলঘর। বিদ্যালয়ের পূর্বদিকে রয়েছে একটি বিশাল খেলার মাঠ, যেখানে প্রতিবছর জমজমাট বার্ষিক ক্রীড়া প্রতিযোগিতার আয়োজন করা হয়। পাশাপাশি, পরীক্ষার্থীদের বিশেষ অধ্যয়নের সুবিধার্থে বিদ্যালয়ের অদূরে একটি অস্থায়ী ছাত্রাবাস এবং নান্দনিক একটি পুকুর রয়েছে।\n\n**শিক্ষা ও প্রশাসনিক পরিবেশ**\nবর্তমান এই প্রতিষ্ঠানে প্রায় ১,২০০ জন শিক্ষার্থী অধ্যয়ন করছে এবং প্রধান শিক্ষক ও সহকারী প্রধান শিক্ষকসহ মোট ২০ জন নিবেদিতপ্রাণ শিক্ষক পাঠদানকার্য পরিচালনা করছেন। এমপিওভুক্ত বিদ্যালয় হওয়ায় এখানে তুলনামূলক সাশ্রয়ী খরচে মানসম্মত শিক্ষা অর্জনের সুব্যবস্থা রয়েছে। ছাত্র-ছাত্রীদের শৃঙ্খলিত রাখতে নির্দিষ্ট ইউনিফর্ম ও পরিচয়পত্র (আইডি কার্ড) ব্যবহারের নিয়ম চালু রয়েছে।\n\n**শিক্ষা ও সহশিক্ষা কার্যক্রমের গৌরব**\n১৯৮১ সালে এমপিওভুক্ত হওয়ার পর ১৯৮৩ সালে প্রথমবারের মতো এসএসসি পরীক্ষায় অংশগ্রহণ করে এই বিদ্যালয়। গ্রেডিং পদ্ধতি চালুর পূর্বে কুমিল্লা বোর্ডের সম্মিলিত মেধা তালিকায় ১ম ও ২য় স্থানসহ নিয়মিত শীর্ষস্থান অর্জনের মাধ্যমে বিদ্যালয়টি অত্র অঞ্চলের একটি ব্যতিক্রমী শিক্ষা প্রতিষ্ঠানে পরিণত হয়। গ্রেডিং পদ্ধতি প্রবর্তনের পরও গোল্ডেন জিপিএ-৫ অর্জনসহ ধারাবাহিক সাফল্যের ধারা অক্ষুণ্ণ রয়েছে। এই প্রতিষ্ঠানের বহু কৃতি শিক্ষার্থী নিজেদের মেধা, যোগ্যতা ও মননশীলতার স্বাক্ষর রেখে দেশ ও বিদেশে সুনামের সাথে সুপ্রতিষ্ঠিত।\n\nশিক্ষাদানের পাশাপাশি শিক্ষার্থীদের সার্বিক বিকাশে সহশিক্ষা কার্যক্রমের ভূমিকা অত্যন্ত প্রশংসনীয়। নিয়মিত পড়াশোনার পাশাপাশি এখানে বি.এন.সি.সি., স্কাউট ও রেড ক্রিসেন্ট-এর কার্যক্রম সুনামের সাথে পরিচালিত হয়। খেলাধুলা, সাংস্কৃতিক কর্মকাণ্ড, বিতর্ক, নাটক ও অভিনয়ে শিক্ষার্থীদের সক্রিয় অংশগ্রহণ নিশ্চিত করতে শিক্ষকমণ্ডলী সর্বদা উৎসাহ প্রদান করেন।\n\nবিদ্যালয়টির ঐতিহ্য বজায় রেখে একে আরও সমৃদ্ধ করার সুদৃঢ় প্রত্যয় নিয়ে প্রধান শিক্ষকের বলিষ্ঠ নেতৃত্বে সকল শিক্ষক ও কর্মকর্তা-কর্মচারী নিরলসভাবে কাজ করে যাচ্ছেন। ছাত্র-ছাত্রীদের উন্নত পঠন-পাঠন, শিক্ষকমণ্ডলীর উচ্চ পেশাদারিত্ব এবং বিদ্যালয় কর্তৃপক্ষের সুব্যবস্থাপনা এই প্রতিষ্ঠানটিকে অনন্য উচ্চতায় আসীন করেছে।', 1, '2023-02-03 13:05:24.209718');
INSERT INTO `school_messages` (`id`, `role`, `heading`, `person_name`, `photo_path`, `message`, `is_active`, `sort_order`, `updated_at`) VALUES
(1, 'president', 'সভাপতির বাণী', 'মাইন উদ্দিন চৌধুরী রিয়াজ', NULL, 'শিক্ষাই জাতির মেরুদণ্ড। ভবানীগঞ্জ বহুমুখী উচ্চ বিদ্যালয়ের শিক্ষার্থীরা যেন জ্ঞান, নৈতিকতা ও সুনাগরিকত্বে সমৃদ্ধ হয়ে দেশ ও সমাজের কল্যাণে নিজেদের নিয়োজিত করতে পারে—এটাই আমাদের প্রত্যাশা। অভিভাবক, শিক্ষক ও পরিচালনা কমিটির সম্মিলিত প্রচেষ্টায় বিদ্যালয়টি তার গৌরবোজ্জ্বল ঐতিহ্য ধরে রাখবে বলে আমি আশাবাদী।', 1, 10, '2026-09-18 13:15:11'),
(2, 'head_teacher', 'প্রধান শিক্ষকের বাণী', 'সিরাজাম মুনির', NULL, 'প্রিয় শিক্ষার্থী, অভিভাবক ও শুভানুধ্যায়ীবৃন্দ, ভবানীগঞ্জ বহুমুখী উচ্চ বিদ্যালয়ে আপনাদের স্বাগতম। আমরা শিক্ষার্থীদের মেধা, চরিত্র ও নেতৃত্ব বিকাশে নিরলসভাবে কাজ করে যাচ্ছি। শৃঙ্খলা, পরিশ্রম ও নৈতিক মূল্যবোধের সমন্বয়ে একটি আদর্শ শিক্ষাঙ্গন গড়ে তোলাই আমাদের অঙ্গীকার।', 1, 20, '2026-09-18 13:15:55');
